// New businesses only, each with a phone or another way to reach it. Exact category matches first, related ones after.
const existing = new Set($input.all().map((i) => i.json.mapsUrl).filter(Boolean));
const rows = $('List the businesses in these places').all().map((i) => i.json).filter((r) => r.mapsUrl);
const today = new Date().toISOString().slice(0, 10);
const order = { exact: 0, close: 1, related: 2 };
return rows
  .filter((r) => !existing.has(r.mapsUrl) && (r.phone || r.bestContact))
  .sort((a, b) => (order[a.categoryMatch] ?? 3) - (order[b.categoryMatch] ?? 3))
  .map((r) => ({ json: {
    foundOn: today, name: r.name, googleCategory: r.googleCategory, match: r.categoryMatch, place: r.placeSearched || r.placeAsked,
    address: r.address, phone: r.phone || '', website: r.website || '', bestContact: r.bestContact || '', contactSource: r.contactSource || '',
    rating: r.rating, reviews: r.reviewsCount, mapsUrl: r.mapsUrl, status: 'new',
  } }));
